import re
from typing import Any, Dict, Iterable, List, Mapping, Optional, Sequence, Set, Tuple, Union


def parse_amount(text: str) -> int:
    """
    Parse a money amount typed by a person or exported from a spreadsheet into
    integer cents.

    Accepted format (surrounding whitespace is ignored):
      * an optional sign, '-' or '+',
      * an optional '$' (after the sign, if there is one),
      * the integer part: one or more digits, optionally using ',' as thousands separator,
      * an optional fractional part: '.' followed by one or two digits.

    Returns the amount in cents as an int. Raises ValueError for anything else, e.g. an
    empty string, a fractional part with three or more digits, or a value without digits.

    Examples:
        parse_amount("12.5") == 1250
        parse_amount("-$1,234.56") == -123456
    """
    if not isinstance(text, str):
        raise ValueError("Input must be a string")

    s = text.strip()
    if not s:
        raise ValueError("Empty string")

    pattern = r'^([+-])?(\$)?(.+)$'
    match = re.match(pattern, s)
    if not match:
        raise ValueError("Invalid format")

    sign_str, dollar_str, number_part = match.groups()
    sign = -1 if sign_str == '-' else 1

    if '.' in number_part:
        parts = number_part.split('.')
        if len(parts) != 2:
            raise ValueError("Multiple decimal points")
        int_part_str, frac_part_str = parts
        if not frac_part_str:
            raise ValueError("Fractional part cannot be empty")
        if len(frac_part_str) > 2:
            raise ValueError("Fractional part must have 1 or 2 digits")
        if not frac_part_str.isdigit():
            raise ValueError("Fractional part must be digits")
        frac_cents = int(frac_part_str) * (10 if len(frac_part_str) == 1 else 1)
    else:
        int_part_str = number_part
        frac_cents = 0

    if not int_part_str:
        raise ValueError("Integer part cannot be empty")

    if ',' in int_part_str:
        groups = int_part_str.split(',')
        if not groups or groups[0] == '':
            raise ValueError("Invalid comma usage")
        if not re.match(r'^\d{1,3}$', groups[0]):
            raise ValueError("First group must be 1-3 digits")
        for g in groups[1:]:
            if not re.match(r'^\d{3}$', g):
                raise ValueError("Subsequent groups must be exactly 3 digits")
        digits_only = ''.join(groups)
    else:
        if not int_part_str.isdigit():
            raise ValueError("Integer part must be digits")
        digits_only = int_part_str

    if not digits_only:
        raise ValueError("No digits found")

    integer_part = int(digits_only)
    total_cents = integer_part * 100 + frac_cents
    return sign * total_cents
"}}

